import pytest


def age_at(born: int, now: int) -> int:
    """Calculate whole years between a birth year and a given year.

    Raises ValueError if now is earlier than born.
    """
    if now < born:
        raise ValueError(f"Current year ({now}) cannot be earlier than birth year ({born})")
    return now - born


def test_age_at_positive() -> None:
    assert age_at(1990, 2024) == 34
    assert age_at(2000, 2001) == 1


def test_age_at_same_year() -> None:
    assert age_at(2024, 2024) == 0


def test_age_at_born_in_future_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)

